const enc = new TextEncoder();
const dec = new TextDecoder('utf-8', {fatal:true});
const FORMAT = 'continuum/encrypted-1';
export function toBase64(bytes){let s='';for(let i=0;i<bytes.length;i+=8192)s+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(s)}
export function fromBase64(s){if(typeof s!=='string'||s.length>12000000||s.length%4||/[^A-Za-z0-9+/=]/.test(s))throw Error('Некорректные зашифрованные данные');const b=Uint8Array.from(atob(s),x=>x.charCodeAt(0));if(toBase64(b)!==s)throw Error('Неканонический base64');return b}
async function derive(password,salt,usage){if(typeof password!=='string'||password.length<12||password.length>1024)throw Error('Пароль должен содержать от 12 до 1024 символов');const material=await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:210000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,[usage])}
export async function encryptCapsule(capsule,password){const bytes=enc.encode(JSON.stringify(capsule));if(bytes.length>8*1024*1024)throw Error('Капсула превышает 8 МБ');const salt=crypto.getRandomValues(new Uint8Array(16));const iv=crypto.getRandomValues(new Uint8Array(12));const key=await derive(password,salt,'encrypt');const ciphertext=await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:enc.encode(FORMAT)},key,bytes);return {format:FORMAT,kdf:'PBKDF2-SHA256',iterations:210000,cipher:'AES-256-GCM',salt:toBase64(salt),iv:toBase64(iv),ciphertext:toBase64(new Uint8Array(ciphertext))}}
export async function decryptCapsule(envelope,password){if(!envelope||typeof envelope!=='object'||Object.keys(envelope).sort().join(',')!==['format','kdf','iterations','cipher','salt','iv','ciphertext'].sort().join(',')||envelope.format!==FORMAT||envelope.kdf!=='PBKDF2-SHA256'||envelope.iterations!==210000||envelope.cipher!=='AES-256-GCM')throw Error('Неподдерживаемый формат шифрования');const salt=fromBase64(envelope.salt),iv=fromBase64(envelope.iv),ciphertext=fromBase64(envelope.ciphertext);if(salt.length!==16||iv.length!==12||ciphertext.length>8*1024*1024+16)throw Error('Некорректный размер зашифрованных данных');try{const key=await derive(password,salt,'decrypt');const bytes=await crypto.subtle.decrypt({name:'AES-GCM',iv,additionalData:enc.encode(FORMAT)},key,ciphertext);return dec.decode(bytes)}catch(e){if(e.message.includes('Пароль должен'))throw e;throw Error('Не удалось расшифровать: неверный пароль или изменённый файл')}}
export function isEncrypted(envelope){return envelope?.format===FORMAT}
